-- Test fixture: the tables the seed writes, shaped like what Hibernate
-- (ddl-auto=update) builds from the entities in backend/src/main/java/com/ssh/entity.
--
-- Written by hand from the entity annotations, NOT generated by Hibernate (the
-- backend could not be built where this was made). Rules applied:
--   * String -> varchar(length, default 255); columnDefinition TEXT -> text
--   * Double -> double precision; LocalDateTime -> timestamp(6)
--   * primitive boolean/int fields -> NOT NULL (boxed Integer/Double stay nullable)
--   * @OneToOne join columns and @UniqueConstraint -> unique
-- tests/test_entity_drift.py checks the seed's columns against the Java sources.
-- Tables the seed does not fill (applications, invitations, audit_logs) are left out.

CREATE TABLE users (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name varchar(100) NOT NULL,
  email varchar(100) NOT NULL UNIQUE,
  password varchar(255) NOT NULL,
  role varchar(20) NOT NULL,
  is_active boolean NOT NULL,
  created_at timestamp(6),
  updated_at timestamp(6)
);

CREATE TABLE smes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL UNIQUE REFERENCES users(id),
  business_name varchar(100) NOT NULL,
  registration_number varchar(20),
  industry varchar(100),
  description varchar(500),
  employee_count integer,
  bbbee_level varchar(50),
  is_verified boolean NOT NULL,
  created_at timestamp(6),
  updated_at timestamp(6)
);

CREATE TABLE youth (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL UNIQUE REFERENCES users(id),
  education varchar(255),
  skills text,
  portfolio text,
  bio text,
  location varchar(100),
  availability varchar(50),
  is_alumni boolean NOT NULL,
  alumni_date timestamp(6),
  ledger_code varchar(32) UNIQUE,
  ledger_share_enabled boolean NOT NULL,
  created_at timestamp(6),
  updated_at timestamp(6)
);

CREATE TABLE skills (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug varchar(100) NOT NULL UNIQUE,
  label varchar(200) NOT NULL,
  category varchar(50),
  esco_uri varchar(500),
  ofo_code varchar(20)
);

CREATE TABLE tasks (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sme_id bigint NOT NULL REFERENCES smes(id),
  assigned_to bigint REFERENCES youth(id),
  title varchar(200) NOT NULL,
  description varchar(1000),
  category varchar(50),
  status varchar(20) NOT NULL,
  budget double precision,
  duration_days integer,
  is_paid boolean NOT NULL,
  revision_reason varchar(1000),
  revision_count integer NOT NULL,
  tier integer,
  reserved_until timestamp(6),
  remote boolean NOT NULL,
  location varchar(100),
  est_hours double precision,
  reflection TEXT,
  created_at timestamp(6),
  updated_at timestamp(6)
);

CREATE TABLE experiences (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  youth_id bigint NOT NULL REFERENCES youth(id),
  task_id bigint NOT NULL REFERENCES tasks(id),
  status varchar(20) NOT NULL,
  start_date timestamp(6),
  end_date timestamp(6),
  feedback varchar(1000),
  is_verified boolean NOT NULL,
  verified_at timestamp(6),
  rating double precision,
  reference varchar(255),
  rejection_reason varchar(1000),
  created_at timestamp(6),
  updated_at timestamp(6),
  CONSTRAINT uk_experience_task UNIQUE (task_id)
);

CREATE TABLE youth_skills (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  youth_id bigint NOT NULL REFERENCES youth(id),
  skill_id bigint NOT NULL REFERENCES skills(id),
  UNIQUE (youth_id, skill_id)
);

CREATE TABLE task_skills (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  task_id bigint NOT NULL REFERENCES tasks(id),
  skill_id bigint NOT NULL REFERENCES skills(id),
  UNIQUE (task_id, skill_id)
);

CREATE TABLE ledger_entries (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  entry_sequence bigint NOT NULL,
  experience_id bigint NOT NULL,
  task_id bigint NOT NULL,
  youth_id bigint NOT NULL,
  rating double precision,
  feedback varchar(1000),
  reference varchar(255),
  verified_at timestamp(6) NOT NULL,
  previous_hash varchar(64) NOT NULL,
  hash varchar(64) NOT NULL,
  created_at timestamp(6),
  CONSTRAINT uk_ledger_sequence UNIQUE (entry_sequence),
  CONSTRAINT uk_ledger_experience UNIQUE (experience_id)
);

CREATE TABLE payments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  task_id bigint NOT NULL REFERENCES tasks(id),
  youth_id bigint NOT NULL REFERENCES youth(id),
  total_amount double precision NOT NULL,
  platform_fee double precision NOT NULL,
  youth_amount double precision NOT NULL,
  status varchar(20) NOT NULL,
  paid_at timestamp(6),
  reference varchar(255),
  created_at timestamp(6),
  updated_at timestamp(6)
);

CREATE TABLE wallets (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name varchar(100) NOT NULL UNIQUE,
  balance double precision NOT NULL,
  currency varchar(3) NOT NULL,
  created_at timestamp(6),
  updated_at timestamp(6)
);

CREATE TABLE wallet_transactions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  wallet_id bigint NOT NULL REFERENCES wallets(id),
  type varchar(10) NOT NULL,
  amount double precision NOT NULL,
  balance_after double precision NOT NULL,
  reference varchar(255),
  created_at timestamp(6)
);
